const staticData = $getWorkflowStaticData('global');
const chatId = $json.message.chat.id.toString();
const text = ($json.message.text || '').trim();

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[chatId]) staticData.sessions[chatId] = { step: 0, data: { products: [] } };

const session = staticData.sessions[chatId];
if (!session.data.products) session.data.products = [];

if (session.step === 0 && text !== '/start') {
  return [{ json: { chatId, userMessage: text, routeTo: 'ai', response: '', checkStock: false, sendToLucas: false, sendQR: false, notifyPayment: false, orderSummary: '', paymentSummary: '', sheetData: {} } }];
}

let response = '';
let checkStock = false;
let productSlug = '';
let productName = '';
let sendToLucas = false;
let sendQR = false;
let notifyPayment = false;
let orderSummary = '';
let paymentSummary = '';
let sheetData = {};

const productMap = {
  'acelga': { name: 'Acelga', slug: 'hortalizas/de-hojas/acelga-agroecologica-mix-variedades-atado' },
  'rucula': { name: 'Rucula', slug: 'hortalizas/de-hojas/rucula-agroecologica-atado' },
  'kale': { name: 'Kale', slug: 'hortalizas/de-hojas/kale-agroecologico-atado' },
  'huevos': { name: 'Huevos de Campo', slug: 'granja/avicola/huevos-de-campo-docena' },
  'puerro': { name: 'Puerro', slug: 'hortalizas/de-raices/puerro-agroecologico-atado' },
  'albahaca': { name: 'Albahaca', slug: 'aromaticas/atados-frescos/albahaca-agroecologica-atado' },
  'ciboulette': { name: 'Ciboulette', slug: 'aromaticas/atados-frescos/cibullete-agroecologico-atado' },
  'cibullete': { name: 'Ciboulette', slug: 'aromaticas/atados-frescos/cibullete-agroecologico-atado' },
  'oregano': { name: 'Oregano', slug: 'aromaticas/oregano-en-hojas-deshidratado-30gr' },
  'laurel': { name: 'Laurel', slug: 'aromaticas/atados-frescos/laurel-agroecologico-fresco-atado' },
  'achicoria': { name: 'Achicoria', slug: 'hortalizas/de-hojas/achicoria-agroecologica-atado' },
  'cebolla': { name: 'Cebolla de Verdeo', slug: 'hortalizas/de-hojas/cebolla-de-verdeo-agroecologica-atado' },
  'ensalada': { name: 'Hojas de Ensalada', slug: 'bolsones-y-mezclum/mezclum/hojas-ensalada-350gr' },
};

const prices = {
  'Acelga': 2800, 'Rucula': 2000, 'Kale': 1800, 'Huevos de Campo': 5000,
  'Puerro': 2500, 'Albahaca': 1600, 'Ciboulette': 1500, 'Oregano': 1800,
  'Laurel': 1000, 'Achicoria': 1000, 'Cebolla de Verdeo': 1800, 'Hojas de Ensalada': 4000,
};

function fmt(n) { return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }

function calcTotal(products) {
  let total = 0;
  for (const item of products) {
    const match = item.match(/^(\d+)\s*x\s*(.+)$/i);
    if (match) total += parseInt(match[1]) * (prices[match[2].trim()] || 0);
  }
  return total;
}

if (text === '/start') {
  session.step = 1;
  response = 'Bienvenido a El Huerto de Lucas!\nPara hacer tu pedido necesito algunos datos.\n\nCual es tu nombre?';

} else if (session.step === 1) {
  session.data.name = text;
  session.step = 2;
  response = 'Gracias ' + text + '! Que producto queres agregar?\n(Escribi el nombre del producto, o listo cuando termines)';

} else if (session.step === 2) {
  const lower = text.toLowerCase();
  if (session.data.awaitingQuantity) {
    const pName = session.data.pendingProductName || 'Producto';
    session.data.products.push(text + ' x ' + pName);
    delete session.data.awaitingQuantity;
    delete session.data.pendingProductName;
    delete session.data.pendingProduct;
    response = text + ' x ' + pName + ' agregado!\nEscribi otro producto o listo para terminar.';
  } else if (lower === 'listo') {
    if (session.data.products.length === 0) {
      response = 'No agregaste ningun producto todavia. Escribi el nombre de un producto para empezar.';
    } else {
      const total = calcTotal(session.data.products);
      const discount = Math.min(Math.round(total * 0.4), 4000);
      session.data.total = total;
      session.step = 3;
      response = 'Tu pedido:\n- ' + session.data.products.join('\n- ') +
        '\n\nTotal: $' + fmt(total) + ' (con Cuenta DNI: $' + fmt(total - discount) + ')' +
        '\n\nComo queres recibir tu pedido?\n1. Envio a domicilio (sin costo, General Pinto)\n2. Retiro en el huerto (Sabados 15 a 18hs)\n3. Retiro en feria (Sabados cada 15 dias, 10 a 12:30hs)';
    }
  } else {
    let found = null;
    for (const [key, val] of Object.entries(productMap)) {
      if (lower.includes(key)) { found = val; break; }
    }
    if (found) {
      checkStock = true;
      productSlug = found.slug;
      productName = found.name;
      session.data.pendingProduct = text;
      session.data.pendingProductName = found.name;
    } else {
      response = 'No encontre ese producto.\nEscribi alguno de estos: Acelga, Kale, Puerro, Rucula, Huevos, Albahaca, Ciboulette, Oregano, Laurel, Achicoria, Cebolla, Ensalada.';
    }
  }

} else if (session.step === 3) {
  if (text === '1') {
    session.data.delivery = 'Envio a domicilio';
    session.step = 4;
    response = 'Envio a domicilio seleccionado.\nCual es tu direccion en General Pinto?';
  } else if (text === '2') {
    session.data.delivery = 'Retiro en el huerto';
    session.data.address = 'Retiro en el huerto (Sabados 15 a 18hs)';
    session.step = 5;
    response = 'Retiro en el huerto seleccionado (Sabados de 15 a 18hs).\nCual es tu numero de telefono?';
  } else if (text === '3') {
    session.data.delivery = 'Retiro en feria';
    session.data.address = 'Retiro en feria (Sabados cada 15 dias, 10 a 12:30hs)';
    session.step = 5;
    response = 'Retiro en feria seleccionado (Sabados cada 15 dias, de 10 a 12:30hs).\nCual es tu numero de telefono?';
  } else {
    response = 'Escribi 1, 2 o 3 para elegir:\n1. Envio a domicilio (sin costo, General Pinto)\n2. Retiro en el huerto (Sabados 15 a 18hs)\n3. Retiro en feria (Sabados c/15 dias, 10 a 12:30hs)';
  }

} else if (session.step === 4) {
  session.data.address = text;
  session.step = 5;
  response = 'Cual es tu numero de telefono?';

} else if (session.step === 5) {
  session.data.phone = text;
  const ahora = new Date();
  const fecha = ahora.toLocaleDateString('es-AR') + ' ' + ahora.toLocaleTimeString('es-AR');
  const totalStr = '$' + fmt(session.data.total || 0);
  sheetData = {
    Fecha: fecha,
    Nombre: session.data.name,
    Productos: session.data.products.join(', '),
    Total: totalStr,
    Entrega: session.data.delivery || '',
    Direccion: session.data.address || '',
    Telefono: text,
    Pago: 'Pendiente'
  };
  orderSummary = 'NUEVO PEDIDO\n\nNombre: ' + session.data.name +
    '\nProductos:\n- ' + session.data.products.join('\n- ') +
    '\nTotal: ' + totalStr +
    '\nEntrega: ' + (session.data.delivery || '') +
    '\nDireccion: ' + (session.data.address || '') +
    '\nTelefono: ' + text +
    '\nPago: PENDIENTE';
  response = 'Perfecto! Tu pedido esta registrado.\n\nComo vas a abonar?\n1. Efectivo (al momento de la entrega/retiro)\n2. Transferencia bancaria';
  sendToLucas = true;
  session.step = 6;

} else if (session.step === 6) {
  if (text === '1') {
    response = 'Pago en efectivo seleccionado. Te contactamos para coordinar. Gracias por elegirnos!';
    staticData.sessions[chatId] = { step: 0, data: { products: [] } };
  } else if (text === '2') {
    response = 'Para transferir usa el alias: lucaspirizmp\nTe mandamos el QR a continuacion.\n\nCuando realices el pago, manda el comprobante por aca.';
    sendQR = true;
    session.step = 7;
  } else {
    response = 'Escribi 1 o 2:\n1. Efectivo (al momento de entrega/retiro)\n2. Transferencia bancaria';
  }

} else if (session.step === 7) {
  const nombre = session.data.name || 'cliente';
  response = 'Comprobante recibido! Tu pago esta confirmado. El pedido queda pendiente de envio. Gracias!';
  paymentSummary = 'PAGO RECIBIDO\n\nCliente: ' + nombre + '\nComprobante de transferencia recibido.\nPedido listo para procesar.';
  notifyPayment = true;
  staticData.sessions[chatId] = { step: 0, data: { products: [] } };
}

return [{ json: { chatId, response, routeTo: 'order', checkStock, productSlug, productName, sendToLucas, sendQR, notifyPayment, orderSummary, paymentSummary, sheetData } }];

const chatId = $('Code Main').item.json.chatId;
const response = $json.output;
return [{ json: { chatId, response } }];

const staticData = $getWorkflowStaticData('global');
const mainData = $('Code Main').item.json;
const chatId = mainData.chatId;
const productName = mainData.productName;
const session = staticData.sessions[chatId];
const html = $json.data || '';
const isOutOfStock = html.includes('product-tag--sin-stock');
let response = '';
if (isOutOfStock) {
  delete session.data.pendingProduct;
  delete session.data.pendingProductName;
  response = 'Lo siento, ' + productName + ' no esta disponible ahora.\nEscribi otro producto o listo para continuar.';
} else {
  session.data.awaitingQuantity = true;
  response = productName + ' disponible! Cuantos atados/unidades queres?';
}
return [{ json: { chatId, response } }];

const d = $json.sheetData;
return [{ json: {
  Fecha: d.Fecha, Nombre: d.Nombre, Productos: d.Productos,
  Total: d.Total, Entrega: d.Entrega, Direccion: d.Direccion,
  Telefono: d.Telefono, Pago: d.Pago || 'Pendiente'
} }];
